def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    candidates = [rng.uniform(lb, ub) for _ in range(dim)]
    best_candidate = clip(candidates)
    best_value = func(best_candidate)

    for _ in range(budget - 1):
        new_candidates = [clip(rng.uniform(lb, ub)) for _ in range(dim)]
        new_value = func(new_candidates)

        if new_value < best_value:
            best_candidate = new_candidates
            best_value = new_value

    return np.array(best_candidate)

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    best = None
    best_func_val = float('inf')

    current_pop = rng.normal(0, 1, size=dim)

    for _ in range(budget):
        candidate = clip(current_pop)

        func_val = func(candidate)

        if func_val < best_func_val:
            best_func_val = func_val
            best = candidate

        sigma = np.std(current_pop)
        current_pop = current_pop + rng.normal(0, 1 / (10 * sigma), size=dim) - current_pop

    return clip(best)
